using namespace std;

vector<bool> overLimit(vector<long long>& times, int n) {
    // Write your solution here
    return vector<bool>(times.size(), false);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m, n;
    cin >> m >> n;
    vector<long long> times(m);
    for (int i = 0; i < m; i++) cin >> times[i];
    vector<bool> res = overLimit(times, n);
    for (int i = 0; i < m; i++) cout << (res[i] ? "YES" : "NO") << '\n';
    return 0;
}

