import java.util.*;
import java.io.*;

public class Main {
    static boolean[] overLimit(long[] times, int n) {
        // Write your solution here
        return new boolean[times.length];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int m = (int) in.nval;
        in.nextToken();
        int n = (int) in.nval;
        long[] times = new long[m];
        for (int i = 0; i < m; i++) {
            in.nextToken();
            times[i] = (long) in.nval;
        }
        boolean[] res = overLimit(times, n);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < m; i++) sb.append(res[i] ? "YES" : "NO").append('\n');
        System.out.print(sb);
    }
}
